35	/**********************/
36	/* Namespace Handling */
37	/**********************/
38	
39	UA_UInt16 addNamespace(UA_Server *server, const UA_String name) {
40	    /* Check if the namespace already exists in the server's namespace array */
41	    for(UA_UInt16 i = 0; i < server->namespacesSize; ++i) {
42	        if(UA_String_equal(&name, &server->namespaces[i]))
43	            return i;
44	    }
45	
46	    /* Make the array bigger */
47	    UA_String *newNS = (UA_String*)UA_realloc(server->namespaces,
48	                                              sizeof(UA_String) * (server->namespacesSize + 1));
49	    if(!newNS)
50	        return 0;
51	    server->namespaces = newNS;
52	
53	    /* Copy the namespace string */
54	    UA_StatusCode retval = UA_String_copy(&name, &server->namespaces[server->namespacesSize]);
55	    if(retval != UA_STATUSCODE_GOOD)
56	        return 0;
57	
58	    /* Announce the change (otherwise, the array appears unchanged) */
59	    ++server->namespacesSize;
60	    return (UA_UInt16)(server->namespacesSize - 1);
61	}
62	
63	UA_UInt16 UA_Server_addNamespace(UA_Server *server, const char* name) {
64	    /* Override const attribute to get string (dirty hack) */
65	    UA_String nameString;
66	    nameString.length = strlen(name);
67	    nameString.data = (UA_Byte*)(uintptr_t)name;
68	    return addNamespace(server, nameString);
69	}
