80	UA_StatusCode
81	UA_Server_getNamespaceByName(UA_Server *server, const UA_String namespaceUri,
82	                             size_t* foundIndex) {
83	  for(size_t idx = 0; idx < server->namespacesSize; idx++)
84	  {
85	    if(UA_String_equal(&server->namespaces[idx], &namespaceUri) == true)
86	    {
87	      (*foundIndex) = idx;
88	      return UA_STATUSCODE_GOOD;
89	    }
90	  }
91	
92	  return UA_STATUSCODE_BADNOTFOUND;
93	}
