95	UA_StatusCode
96	UA_Server_forEachChildNodeCall(UA_Server *server, UA_NodeId parentNodeId,
97	                               UA_NodeIteratorCallback callback, void *handle) {
98	    const UA_Node *parent =
99	        server->config.nodestore.getNode(server->config.nodestore.context,
100	                                         &parentNodeId);
101	    if(!parent)
102	        return UA_STATUSCODE_BADNODEIDINVALID;
103	
104	    /* TODO: We need to do an ugly copy of the references array since users may
105	     * delete references from within the callback. In single-threaded mode this
106	     * changes the same node we point at here. In multi-threaded mode, this
107	     * creates a new copy as nodes are truly immutable.
108	     * The callback could remove a node via the regular public API.
109	     * This can remove a member of the nodes-array we iterate over...
110	     * */
111	    UA_Node *parentCopy = UA_Node_copy_alloc(parent);
112	    if(!parentCopy) {
113	        server->config.nodestore.releaseNode(server->config.nodestore.context, parent);
114	        return UA_STATUSCODE_BADUNEXPECTEDERROR;
115	    }
116	
117	    UA_StatusCode retval = UA_STATUSCODE_GOOD;
118	    for(size_t i = parentCopy->referencesSize; i > 0; --i) {
119	        UA_NodeReferenceKind *ref = &parentCopy->references[i - 1];
120	        for(size_t j = 0; j<ref->targetIdsSize; j++) {
121	            retval = callback(ref->targetIds[j].nodeId, ref->isInverse,
122	                              ref->referenceTypeId, handle);
123	            if(retval != UA_STATUSCODE_GOOD)
124	                goto cleanup;
125	        }
126	    }
127	
128	cleanup:
129	    UA_Node_deleteMembers(parentCopy);
130	    UA_free(parentCopy);
131	
132	    server->config.nodestore.releaseNode(server->config.nodestore.context, parent);
133	    return retval;
134	}
