227	/* Recurring cleanup. Removing unused and timed-out channels and sessions */
228	static void
229	UA_Server_cleanup(UA_Server *server, void *_) {
230	    UA_DateTime nowMonotonic = UA_DateTime_nowMonotonic();
231	    UA_SessionManager_cleanupTimedOut(&server->sessionManager, nowMonotonic);
232	    UA_SecureChannelManager_cleanupTimedOut(&server->secureChannelManager, nowMonotonic);
233	#ifdef UA_ENABLE_DISCOVERY
234	    UA_Discovery_cleanupTimedOut(server, nowMonotonic);
235	#endif
236	}
