238	/********************/
239	/* Server Lifecycle */
240	/********************/
241	
242	UA_Server *
243	UA_Server_new(const UA_ServerConfig *config) {
244	    /* A config is required */
245	    if(!config)
246	        return NULL;
247	
248	    /* Allocate the server */
249	    UA_Server *server = (UA_Server *)UA_calloc(1, sizeof(UA_Server));
250	    if(!server)
251	        return NULL;
252	
253	    /* Set the config */
254	    server->config = *config;
255	
256	    /* Init start time to zero, the actual start time will be sampled in
257	     * UA_Server_run_startup() */
258	    server->startTime = 0;
259	
260	    /* Set a seed for non-cyptographic randomness */
261	#ifndef UA_ENABLE_DETERMINISTIC_RNG
262	    UA_random_seed((UA_UInt64)UA_DateTime_now());
263	#endif
264	
265	    /* Initialize the handling of repeated callbacks */
266	    UA_Timer_init(&server->timer);
267	
268	    UA_WorkQueue_init(&server->workQueue);
269	
270	    /* Initialize the adminSession */
271	    UA_Session_init(&server->adminSession);
272	    server->adminSession.sessionId.identifierType = UA_NODEIDTYPE_GUID;
273	    server->adminSession.sessionId.identifier.guid.data1 = 1;
274	    server->adminSession.validTill = UA_INT64_MAX;
275	
276	    /* Create Namespaces 0 and 1 */
277	    server->namespaces = (UA_String *)UA_Array_new(2, &UA_TYPES[UA_TYPES_STRING]);
278	    server->namespaces[0] = UA_STRING_ALLOC("http://opcfoundation.org/UA/");
279	    UA_String_copy(&server->config.applicationDescription.applicationUri, &server->namespaces[1]);
280	    server->namespacesSize = 2;
281	
282	    /* Initialized SecureChannel and Session managers */
283	    UA_SecureChannelManager_init(&server->secureChannelManager, server);
284	    UA_SessionManager_init(&server->sessionManager, server);
285	
286	    /* Add a regular callback for cleanup and maintenance */
287	    UA_Server_addRepeatedCallback(server, (UA_ServerCallback)UA_Server_cleanup, NULL,
288	                                  10000, NULL);
289	
290	    /* Initialized discovery database */
291	#ifdef UA_ENABLE_DISCOVERY
292	    LIST_INIT(&server->registeredServers);
293	    server->registeredServersSize = 0;
294	    LIST_INIT(&server->periodicServerRegisterCallbacks);
295	    server->registerServerCallback = NULL;
296	    server->registerServerCallbackData = NULL;
297	#endif
298	
299	    /* Initialize multicast discovery */
300	#if defined(UA_ENABLE_DISCOVERY) && defined(UA_ENABLE_DISCOVERY_MULTICAST)
301	    server->mdnsDaemon = NULL;
302	    server->mdnsSocket = UA_INVALID_SOCKET;
303	    server->mdnsMainSrvAdded = UA_FALSE;
304	    if(server->config.applicationDescription.applicationType == UA_APPLICATIONTYPE_DISCOVERYSERVER)
305	        initMulticastDiscoveryServer(server);
306	
307	    LIST_INIT(&server->serverOnNetwork);
308	    server->serverOnNetworkSize = 0;
309	    server->serverOnNetworkRecordIdCounter = 0;
310	    server->serverOnNetworkRecordIdLastReset = UA_DateTime_now();
311	    memset(server->serverOnNetworkHash, 0,
312	           sizeof(struct serverOnNetwork_hash_entry*) * SERVER_ON_NETWORK_HASH_PRIME);
313	
314	
315	    LIST_INIT(&server->mdnsHostnameToIp);
316	    memset(server->mdnsHostnameToIpHash, 0,
317	           sizeof(struct mdnsHostnameToIp_hash_entry*) * MDNS_HOSTNAME_TO_IP_HASH_PRIME);
318	
319	    server->serverOnNetworkCallback = NULL;
320	    server->serverOnNetworkCallbackData = NULL;
321	#endif
322	
323	    /* Initialize namespace 0*/
324	    UA_StatusCode retVal = UA_Server_initNS0(server);
325	    if(retVal != UA_STATUSCODE_GOOD) {
326	        UA_LOG_ERROR(config->logger, UA_LOGCATEGORY_SERVER,
327	                     "Namespace 0 could not be bootstrapped with error %s. "
328	                     "Shutting down the server.",
329	                     UA_StatusCode_name(retVal));
330	        UA_Server_delete(server);
331	        return NULL;
332	    }
333	    /* Build PubSub information model */
334	#ifdef UA_ENABLE_PUBSUB_INFORMATIONMODEL
335	    UA_Server_initPubSubNS0(server);
336	#endif
337	
338	    return server;
339	}
