365	UA_StatusCode UA_EXPORT
366	UA_Server_updateCertificate(UA_Server *server,
367	                            const UA_ByteString *oldCertificate,
368	                            const UA_ByteString *newCertificate,
369	                            const UA_ByteString *newPrivateKey,
370	                            UA_Boolean closeSessions,
371	                            UA_Boolean closeSecureChannels) {
372	
373	    if (server == NULL || oldCertificate == NULL
374	        || newCertificate == NULL || newPrivateKey == NULL) {
375	        return UA_STATUSCODE_BADINTERNALERROR;
376	    }
377	
378	    if (closeSessions) {
379	        UA_SessionManager *sm = &server->sessionManager;
380	        session_list_entry *current;
381	        LIST_FOREACH(current, &sm->sessions, pointers) {
382	            if (UA_ByteString_equal(oldCertificate,
383	                                    &current->session.header.channel->securityPolicy->localCertificate)) {
384	                UA_SessionManager_removeSession(sm, &current->session.header.authenticationToken);
385	            }
386	        }
387	
388	    }
389	
390	    if (closeSecureChannels) {
391	        UA_SecureChannelManager *cm = &server->secureChannelManager;
392	        channel_entry *entry;
393	        TAILQ_FOREACH(entry, &cm->channels, pointers) {
394	            if(UA_ByteString_equal(&entry->channel.securityPolicy->localCertificate, oldCertificate)){
395	                UA_SecureChannelManager_close(cm, entry->channel.securityToken.channelId);
396	            }
397	        }
398	    }
399	
400	    size_t index = 0;
401	    while (index < server->config.endpointsSize) {
402	        UA_EndpointDescription *ed = &server->config.endpoints[index].endpointDescription;
403	        if (UA_ByteString_equal(&ed->serverCertificate, oldCertificate)) {
404	            UA_String_deleteMembers(&ed->serverCertificate);
405	            UA_String_copy(newCertificate, &ed->serverCertificate);
406	            UA_SecurityPolicy *sp = &server->config.endpoints[index].securityPolicy;
407	            sp->updateCertificateAndPrivateKey(sp, *newCertificate, *newPrivateKey);
408	        }
409	        index++;
410	    }
411	
412	    return UA_STATUSCODE_GOOD;
413	}
