415	/********************/
416	/* Main Server Loop */
417	/********************/
418	
419	#define UA_MAXTIMEOUT 50 /* Max timeout in ms between main-loop iterations */
420	
421	/* Start: Spin up the workers and the network layer and sample the server's
422	 *        start time.
423	 * Iterate: Process repeated callbacks and events in the network layer. This
424	 *          part can be driven from an external main-loop in an event-driven
425	 *          single-threaded architecture.
426	 * Stop: Stop workers, finish all callbacks, stop the network layer, clean up */
427	
428	UA_StatusCode
429	UA_Server_run_startup(UA_Server *server) {
430	    UA_Variant var;
431	    UA_StatusCode result = UA_STATUSCODE_GOOD;
432		
433		/* At least one endpoint has to be configured */
434	    if(server->config.endpointsSize == 0) {
435	        UA_LOG_WARNING(server->config.logger, UA_LOGCATEGORY_SERVER,
436	                       "There has to be at least one endpoint.");
437	    }
438	
439	    /* Sample the start time and set it to the Server object */
440	    server->startTime = UA_DateTime_now();
441	    UA_Variant_init(&var);
442	    UA_Variant_setScalar(&var, &server->startTime, &UA_TYPES[UA_TYPES_DATETIME]);
443	    UA_Server_writeValue(server,
444	                         UA_NODEID_NUMERIC(0, UA_NS0ID_SERVER_SERVERSTATUS_STARTTIME),
445	                         var);
446	
447	    /* Start the networklayers */
448	    for(size_t i = 0; i < server->config.networkLayersSize; ++i) {
449	        UA_ServerNetworkLayer *nl = &server->config.networkLayers[i];
450	        result |= nl->start(nl, &server->config.customHostname);
451	    }
452	
453	    /* Spin up the worker threads */
454	#ifdef UA_ENABLE_MULTITHREADING
455	    UA_LOG_INFO(server->config.logger, UA_LOGCATEGORY_SERVER,
456	                "Spinning up %u worker thread(s)", server->config.nThreads);
457	    UA_WorkQueue_start(&server->workQueue, server->config.nThreads);
458	#endif
459	
460	    /* Start the multicast discovery server */
461	#ifdef UA_ENABLE_DISCOVERY_MULTICAST
462	    if(server->config.applicationDescription.applicationType ==
463	       UA_APPLICATIONTYPE_DISCOVERYSERVER)
464	        startMulticastDiscoveryServer(server);
465	#endif
466	
467	    return result;
468	}
469	
470	static void
471	serverExecuteRepeatedCallback(UA_Server *server, UA_ApplicationCallback cb,
472	                        void *callbackApplication, void *data) {
473	#ifndef UA_ENABLE_MULTITHREADING
474	    cb(callbackApplication, data);
475	#else
476	    UA_WorkQueue_enqueue(&server->workQueue, cb, callbackApplication, data);
477	#endif
478	}
479	
480	UA_UInt16
481	UA_Server_run_iterate(UA_Server *server, UA_Boolean waitInternal) {
482	    /* Process repeated work */
483	    UA_DateTime now = UA_DateTime_nowMonotonic();
484	    UA_DateTime nextRepeated = UA_Timer_process(&server->timer, now,
485	                     (UA_TimerExecutionCallback)serverExecuteRepeatedCallback, server);
486	    UA_DateTime latest = now + (UA_MAXTIMEOUT * UA_DATETIME_MSEC);
487	    if(nextRepeated > latest)
488	        nextRepeated = latest;
489	
490	    UA_UInt16 timeout = 0;
491	
492	    /* round always to upper value to avoid timeout to be set to 0
493	    * if(nextRepeated - now) < (UA_DATETIME_MSEC/2) */
494	    if(waitInternal)
495	        timeout = (UA_UInt16)(((nextRepeated - now) + (UA_DATETIME_MSEC - 1)) / UA_DATETIME_MSEC);
496	
497	    /* Listen on the networklayer */
498	    for(size_t i = 0; i < server->config.networkLayersSize; ++i) {
499	        UA_ServerNetworkLayer *nl = &server->config.networkLayers[i];
500	        nl->listen(nl, server, timeout);
501	    }
502	
503	#if defined(UA_ENABLE_DISCOVERY_MULTICAST) && !defined(UA_ENABLE_MULTITHREADING)
504	    if(server->config.applicationDescription.applicationType ==
505	       UA_APPLICATIONTYPE_DISCOVERYSERVER) {
506	        // TODO multicastNextRepeat does not consider new input data (requests)
507	        // on the socket. It will be handled on the next call. if needed, we
508	        // need to use select with timeout on the multicast socket
509	        // server->mdnsSocket (see example in mdnsd library) on higher level.
510	        UA_DateTime multicastNextRepeat = 0;
511	        UA_StatusCode hasNext =
512	            iterateMulticastDiscoveryServer(server, &multicastNextRepeat, UA_TRUE);
513	        if(hasNext == UA_STATUSCODE_GOOD && multicastNextRepeat < nextRepeated)
514	            nextRepeated = multicastNextRepeat;
515	    }
516	#endif
517	
518	#ifndef UA_ENABLE_MULTITHREADING
519	    UA_WorkQueue_manuallyProcessDelayed(&server->workQueue);
520	#endif
521	
522	    now = UA_DateTime_nowMonotonic();
523	    timeout = 0;
524	    if(nextRepeated > now)
525	        timeout = (UA_UInt16)((nextRepeated - now) / UA_DATETIME_MSEC);
526	    return timeout;
527	}
528	
529	UA_StatusCode
530	UA_Server_run_shutdown(UA_Server *server) {
531	    /* Stop the netowrk layer */
532	    for(size_t i = 0; i < server->config.networkLayersSize; ++i) {
533	        UA_ServerNetworkLayer *nl = &server->config.networkLayers[i];
534	        nl->stop(nl, server);
535	    }
536	
537	#ifdef UA_ENABLE_MULTITHREADING
538	    /* Shut down the workers */
539	    UA_LOG_INFO(server->config.logger, UA_LOGCATEGORY_SERVER,
540	                "Shutting down %u worker thread(s)",
541	                (UA_UInt32)server->workQueue.workersSize);
542	    UA_WorkQueue_stop(&server->workQueue);
543	#endif
544	
545	#ifdef UA_ENABLE_DISCOVERY_MULTICAST
546	    /* Stop multicast discovery */
547	    if(server->config.applicationDescription.applicationType ==
548	       UA_APPLICATIONTYPE_DISCOVERYSERVER)
549	        stopMulticastDiscoveryServer(server);
550	#endif
551	
552	    /* Execute all delayed callbacks */
553	    UA_WorkQueue_cleanup(&server->workQueue);
554	
555	    return UA_STATUSCODE_GOOD;
556	}
557	
558	UA_StatusCode
559	UA_Server_run(UA_Server *server, volatile UA_Boolean *running) {
560	    UA_StatusCode retval = UA_Server_run_startup(server);
561	    if(retval != UA_STATUSCODE_GOOD)
562	        return retval;
563	#ifdef UA_ENABLE_VALGRIND_INTERACTIVE
564	    size_t loopCount = 0;
565	#endif
566	    while(*running) {
567	#ifdef UA_ENABLE_VALGRIND_INTERACTIVE
568	        if(loopCount == 0) {
569	            VALGRIND_DO_LEAK_CHECK;
570	        }
571	        ++loopCount;
572	        loopCount %= UA_VALGRIND_INTERACTIVE_INTERVAL;
573	#endif
574	        UA_Server_run_iterate(server, true);
575	    }
576	    return UA_Server_run_shutdown(server);
577	}
