23	
24	void
25	UA_Notification_enqueue(UA_Server *server, UA_Subscription *sub,
26	                        UA_MonitoredItem *mon, UA_Notification *n) {
27	    /* Add to the MonitoredItem */
28	    TAILQ_INSERT_TAIL(&mon->queue, n, listEntry);
29	    ++mon->queueSize;
30	
31	    /* Add to the subscription */
32	    TAILQ_INSERT_TAIL(&sub->notificationQueue, n, globalEntry);
33	    ++sub->notificationQueueSize;
34	    if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_CHANGENOTIFY) {
35	        ++sub->dataChangeNotifications;
36	    } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_EVENTNOTIFY) {
37	        ++sub->eventNotifications;
38	    } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_STATUSNOTIFY) {
39	        ++sub->statusChangeNotifications;
40	    }
41	
42	    /* Ensure enough space is available in the MonitoredItem. Do this only after
43	     * adding the new Notification. */
44	    UA_MonitoredItem_ensureQueueSpace(server, mon);
45	}
46	
47	void
48	UA_Notification_delete(UA_Subscription *sub, UA_MonitoredItem *mon,
49	                       UA_Notification *n) {
50	    if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_CHANGENOTIFY) {
51	        UA_DataValue_deleteMembers(&n->data.value);
52	        --sub->dataChangeNotifications;
53	#ifdef UA_ENABLE_SUBSCRIPTIONS_EVENTS
54	    } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_EVENTNOTIFY) {
55	        UA_EventFieldList_deleteMembers(&n->data.event.fields);
56	        /* EventFilterResult currently isn't being used
57	         * UA_EventFilterResult_delete(notification->data.event->result); */
58	        --sub->eventNotifications;
59	#endif
60	    } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_STATUSNOTIFY) {
61	        --sub->statusChangeNotifications;
62	    }
63	
64	    TAILQ_REMOVE(&mon->queue, n, listEntry);
65	    --mon->queueSize;
66	
67	    TAILQ_REMOVE(&sub->notificationQueue, n, globalEntry);
68	    --sub->notificationQueueSize;
69	
70	    UA_free(n);
71	}
72	
73	UA_Subscription *
74	UA_Subscription_new(UA_Session *session, UA_UInt32 subscriptionId) {
75	    /* Allocate the memory */
76	    UA_Subscription *newSub =
77	        (UA_Subscription*)UA_calloc(1, sizeof(UA_Subscription));
78	    if(!newSub)
79	        return NULL;
80	
81	    /* Remaining members are covered by calloc zeroing out the memory */
82	    newSub->session = session;
83	    newSub->subscriptionId = subscriptionId;
84	    newSub->state = UA_SUBSCRIPTIONSTATE_NORMAL; /* The first publish response is sent immediately */
85	    /* Even if the first publish response is a keepalive the sequence number is 1.
86	     * This can happen by a subscription without a monitored item (see CTT test scripts). */
87	    newSub->nextSequenceNumber = 1;
88	    TAILQ_INIT(&newSub->retransmissionQueue);
89	    TAILQ_INIT(&newSub->notificationQueue);
90	    return newSub;
91	}
92	
93	void
94	UA_Subscription_deleteMembers(UA_Server *server, UA_Subscription *sub) {
95	    UA_LOG_DEBUG_SESSION(server->config.logger, sub->session, "Subscription %u | "
96	                             "Delete the subscription", sub->subscriptionId);
97	
98	    Subscription_unregisterPublishCallback(server, sub);
99	
100	    /* Delete monitored Items */
101	    UA_MonitoredItem *mon, *tmp_mon;
102	    LIST_FOREACH_SAFE(mon, &sub->monitoredItems, listEntry, tmp_mon) {
103	        LIST_REMOVE(mon, listEntry);
104	        UA_MonitoredItem_delete(server, mon);
105	    }
106	    sub->monitoredItemsSize = 0;
107	
108	    /* Delete Retransmission Queue */
109	    UA_NotificationMessageEntry *nme, *nme_tmp;
110	    TAILQ_FOREACH_SAFE(nme, &sub->retransmissionQueue, listEntry, nme_tmp) {
111	        TAILQ_REMOVE(&sub->retransmissionQueue, nme, listEntry);
112	        UA_NotificationMessage_deleteMembers(&nme->message);
113	        UA_free(nme);
114	    }
115	    sub->retransmissionQueueSize = 0;
116	}
117	
118	UA_MonitoredItem *
119	UA_Subscription_getMonitoredItem(UA_Subscription *sub, UA_UInt32 monitoredItemId) {
120	    UA_MonitoredItem *mon;
121	    LIST_FOREACH(mon, &sub->monitoredItems, listEntry) {
122	        if(mon->monitoredItemId == monitoredItemId)
123	            break;
124	    }
125	    return mon;
126	}
127	
128	UA_StatusCode
129	UA_Subscription_deleteMonitoredItem(UA_Server *server, UA_Subscription *sub,
130	                                    UA_UInt32 monitoredItemId) {
131	    /* Find the MonitoredItem */
132	    UA_MonitoredItem *mon;
133	    LIST_FOREACH(mon, &sub->monitoredItems, listEntry) {
134	        if(mon->monitoredItemId == monitoredItemId)
135	            break;
136	    }
137	    if(!mon)
138	        return UA_STATUSCODE_BADMONITOREDITEMIDINVALID;
139	
140	    /* Remove the MonitoredItem */
141	    LIST_REMOVE(mon, listEntry);
142	    sub->monitoredItemsSize--;
143	
144	    /* Remove content and delayed free */
145	    UA_MonitoredItem_delete(server, mon);
146	
147	    return UA_STATUSCODE_GOOD;
148	}
149	
150	void
151	UA_Subscription_addMonitoredItem(UA_Subscription *sub, UA_MonitoredItem *newMon) {
152	    sub->monitoredItemsSize++;
153	    LIST_INSERT_HEAD(&sub->monitoredItems, newMon, listEntry);
154	}
155	
156	static void
157	UA_Subscription_addRetransmissionMessage(UA_Server *server, UA_Subscription *sub,
158	                                         UA_NotificationMessageEntry *entry) {
159	    /* Release the oldest entry if there is not enough space */
160	    if(server->config.maxRetransmissionQueueSize > 0 &&
161	       sub->retransmissionQueueSize >= server->config.maxRetransmissionQueueSize) {
162	        UA_NotificationMessageEntry *lastentry =
163	            TAILQ_LAST(&sub->retransmissionQueue, ListOfNotificationMessages);
164	        TAILQ_REMOVE(&sub->retransmissionQueue, lastentry, listEntry);
165	        --sub->retransmissionQueueSize;
166	        UA_NotificationMessage_deleteMembers(&lastentry->message);
167	        UA_free(lastentry);
168	    }
169	
170	    /* Add entry */
171	    TAILQ_INSERT_TAIL(&sub->retransmissionQueue, entry, listEntry);
172	    ++sub->retransmissionQueueSize;
173	}
174	
175	UA_StatusCode
176	UA_Subscription_removeRetransmissionMessage(UA_Subscription *sub, UA_UInt32 sequenceNumber) {
177	    /* Find the retransmission message */
178	    UA_NotificationMessageEntry *entry;
179	    TAILQ_FOREACH(entry, &sub->retransmissionQueue, listEntry) {
180	        if(entry->message.sequenceNumber == sequenceNumber)
181	            break;
182	    }
183	    if(!entry)
184	        return UA_STATUSCODE_BADSEQUENCENUMBERUNKNOWN;
185	
186	    /* Remove the retransmission message */
187	    TAILQ_REMOVE(&sub->retransmissionQueue, entry, listEntry);
188	    --sub->retransmissionQueueSize;
189	    UA_NotificationMessage_deleteMembers(&entry->message);
190	    UA_free(entry);
191	    return UA_STATUSCODE_GOOD;
192	}
193	
194	static UA_StatusCode
195	prepareNotificationMessage(UA_Server *server, UA_Subscription *sub,
196	                           UA_NotificationMessage *message, size_t notifications) {
197	    UA_assert(notifications > 0);
198	
199	    /* Allocate an ExtensionObject for events and data */
200	    message->notificationData = (UA_ExtensionObject*)
201	        UA_Array_new(2, &UA_TYPES[UA_TYPES_EXTENSIONOBJECT]);
202	    if(!message->notificationData)
203	        return UA_STATUSCODE_BADOUTOFMEMORY;
204	    message->notificationDataSize = 2;
205	
206	    /* Pre-allocate DataChangeNotifications */
207	    size_t notificationDataIdx = 0;
208	    UA_DataChangeNotification *dcn = NULL;
209	    if(sub->dataChangeNotifications > 0) {
210	        dcn = UA_DataChangeNotification_new();
211	        if(!dcn) {
212	            UA_NotificationMessage_deleteMembers(message);
213	            return UA_STATUSCODE_BADOUTOFMEMORY;
214	        }
215	        message->notificationData->encoding = UA_EXTENSIONOBJECT_DECODED;
216	        message->notificationData->content.decoded.data = dcn;
217	        message->notificationData->content.decoded.type = &UA_TYPES[UA_TYPES_DATACHANGENOTIFICATION];
218	
219	        size_t dcnSize = sub->dataChangeNotifications;
220	        if(dcnSize > notifications)
221	            dcnSize = notifications;
222	        dcn->monitoredItems = (UA_MonitoredItemNotification*)
223	            UA_Array_new(dcnSize, &UA_TYPES[UA_TYPES_MONITOREDITEMNOTIFICATION]);
224	        if(!dcn->monitoredItems) {
225	            UA_NotificationMessage_deleteMembers(message);
226	            return UA_STATUSCODE_BADOUTOFMEMORY;
227	        }
228	        dcn->monitoredItemsSize = dcnSize;
229	        notificationDataIdx++;
230	    }
231	
232	#ifdef UA_ENABLE_SUBSCRIPTIONS_EVENTS
233	    UA_EventNotificationList *enl = NULL;
234	    UA_StatusChangeNotification *scn = NULL;
235	    /* Pre-allocate either StatusChange or EventNotifications. Sending a
236	     * (single) StatusChangeNotification has priority. */
237	    if(sub->statusChangeNotifications > 0) {
238	        scn = UA_StatusChangeNotification_new();
239	        if(!scn) {
240	            UA_NotificationMessage_deleteMembers(message);
241	            return UA_STATUSCODE_BADOUTOFMEMORY;
242	        }
243	        message->notificationData[notificationDataIdx].encoding = UA_EXTENSIONOBJECT_DECODED;
244	        message->notificationData[notificationDataIdx].content.decoded.data = scn;
245	        message->notificationData[notificationDataIdx].content.decoded.type = &UA_TYPES[UA_TYPES_STATUSCHANGENOTIFICATION];
246	        notificationDataIdx++;
247	    } else if(sub->eventNotifications > 0) {
248	        enl = UA_EventNotificationList_new();
249	        if(!enl) {
250	            UA_NotificationMessage_deleteMembers(message);
251	            return UA_STATUSCODE_BADOUTOFMEMORY;
252	        }
253	        message->notificationData[notificationDataIdx].encoding = UA_EXTENSIONOBJECT_DECODED;
254	        message->notificationData[notificationDataIdx].content.decoded.data = enl;
255	        message->notificationData[notificationDataIdx].content.decoded.type = &UA_TYPES[UA_TYPES_EVENTNOTIFICATIONLIST];
256	
257	        size_t enlSize = sub->eventNotifications;
258	        if(enlSize > notifications)
259	            enlSize = notifications;
260	        enl->events = (UA_EventFieldList*) UA_Array_new(enlSize, &UA_TYPES[UA_TYPES_EVENTFIELDLIST]);
261	        if(!enl->events) {
262	            UA_NotificationMessage_deleteMembers(message);
263	            return UA_STATUSCODE_BADOUTOFMEMORY;
264	        }
265	        enl->eventsSize = enlSize;
266	        notificationDataIdx++;
267	    }
268	#endif
269	
270	    UA_assert(notificationDataIdx > 0);
271	    message->notificationDataSize = notificationDataIdx;
272	
273	    /* <-- The point of no return --> */
274	
275	    size_t totalNotifications = 0; /* How many notifications were moved to the response overall? */
276	    size_t dcnPos = 0; /* How many DataChangeNotifications were put into the list? */
277	#ifdef UA_ENABLE_SUBSCRIPTIONS_EVENTS
278	    size_t enlPos = 0; /* How many EventNotifications were moved into the list */
279	#endif
280	    UA_Notification *notification, *notification_tmp;
281	    TAILQ_FOREACH_SAFE(notification, &sub->notificationQueue, globalEntry, notification_tmp) {
282	        if(totalNotifications >= notifications)
283	            break;
284	        
285	        UA_MonitoredItem *mon = notification->mon;
286	
287	        /* Move the content to the response */
288	        if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_CHANGENOTIFY) {
289	            UA_assert(dcn != NULL); /* Have at least one change notification */
290	            /* Move the content to the response */
291	            UA_MonitoredItemNotification *min = &dcn->monitoredItems[dcnPos];
292	            min->clientHandle = mon->clientHandle;
293	            min->value = notification->data.value;
294	            UA_DataValue_init(&notification->data.value); /* Reset after the value has been moved */
295	            dcnPos++;
296	        }
297	#ifdef UA_ENABLE_SUBSCRIPTIONS_EVENTS
298	        else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_STATUSNOTIFY && scn) {
299	            // TODO: Handling of StatusChangeNotifications
300	            scn = NULL; /* At most one per PublishReponse */
301	        } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_EVENTNOTIFY && enl) {
302	            UA_assert(enl != NULL); /* Have at least one event notification */
303	
304	            /* Move the content to the response */
305	            UA_EventFieldList *efl = &enl->events[enlPos];
306	            *efl = notification->data.event.fields;
307	            UA_EventFieldList_init(&notification->data.event.fields);
308	            efl->clientHandle = mon->clientHandle;
309	            enlPos++;
310	        }
311	#endif
312	        else {
313	            continue; /* Nothing to do */
314	        }
315	
316	        /* Remove the notification from the queues */
317	        UA_Notification_delete(sub, mon, notification);
318	        totalNotifications++;
319	    }
320	
321	    /* Set sizes */
322	    if(dcn) {
323	        dcn->monitoredItemsSize = dcnPos;
324	        if(dcnPos == 0) {
325	            UA_free(dcn->monitoredItems);
326	            dcn->monitoredItems = NULL;
327	        }
328	    }
329	
330	#ifdef UA_ENABLE_SUBSCRIPTIONS_EVENTS
331	    if(enl) {
332	        enl->eventsSize = enlPos;
333	        if(enlPos == 0) {
334	            UA_free(enl->events);
335	            enl->events = NULL;
336	        }
337	    }
338	#endif
339	
340	    return UA_STATUSCODE_GOOD;
341	}
342	
343	/* According to OPC Unified Architecture, Part 4 5.13.1.1 i) The value 0 is
344	 * never used for the sequence number */
345	static UA_UInt32
346	UA_Subscription_nextSequenceNumber(UA_UInt32 sequenceNumber) {
347	    UA_UInt32 nextSequenceNumber = sequenceNumber + 1;
348	    if(nextSequenceNumber == 0)
349	        nextSequenceNumber = 1;
350	    return nextSequenceNumber;
351	}
352	
353	static void
354	publishCallback(UA_Server *server, UA_Subscription *sub) {
355	    sub->readyNotifications = sub->notificationQueueSize;
356	    UA_Subscription_publish(server, sub);
357	}
358	
359	void
360	UA_Subscription_publish(UA_Server *server, UA_Subscription *sub) {
361	    UA_LOG_DEBUG_SESSION(server->config.logger, sub->session, "Subscription %u | "
362	                         "Publish Callback", sub->subscriptionId);
363	    /* Dequeue a response */
364	    UA_PublishResponseEntry *pre = UA_Session_dequeuePublishReq(sub->session);
365	    if(pre) {
366	        sub->currentLifetimeCount = 0; /* Reset the LifetimeCounter */
367	    } else {
368	        UA_LOG_DEBUG_SESSION(server->config.logger, sub->session,
369	                             "Subscription %u | The publish queue is empty",
370	                             sub->subscriptionId);
371	        ++sub->currentLifetimeCount;
372	
373	        if(sub->currentLifetimeCount > sub->lifeTimeCount) {
374	            UA_LOG_DEBUG_SESSION(server->config.logger, sub->session,
375	                                 "Subscription %u | End of lifetime "
376	                                 "for subscription", sub->subscriptionId);
377	            UA_Session_deleteSubscription(server, sub->session, sub->subscriptionId);
378	            /* TODO: send a StatusChangeNotification with Bad_Timeout */
379	            return;
380	        }
381	    }
382	
383	    /* If there are several late publish responses... */
384	    if(sub->readyNotifications > sub->notificationQueueSize)
385	        sub->readyNotifications = sub->notificationQueueSize;
386	
387	    /* Count the available notifications */
388	    UA_UInt32 notifications = sub->readyNotifications;
389	    if(!sub->publishingEnabled)
390	        notifications = 0;
391	
392	    UA_Boolean moreNotifications = false;
393	    if(notifications > sub->notificationsPerPublish) {
394	        notifications = sub->notificationsPerPublish;
395	        moreNotifications = true;
396	    }
397	
398	    /* Return if no notifications and no keepalive */
399	    if(notifications == 0) {
400	        ++sub->currentKeepAliveCount;
401	        if(sub->currentKeepAliveCount < sub->maxKeepAliveCount) {
402	            if(pre)
403	                UA_Session_queuePublishReq(sub->session, pre, true); /* Re-enqueue */
404	            return;
405	        }
406	        UA_LOG_DEBUG_SESSION(server->config.logger, sub->session,
407	                             "Subscription %u | Sending a KeepAlive",
408	                             sub->subscriptionId);
409	    }
410	
411	    /* We want to send a response. Is the channel open? */
412	    UA_SecureChannel *channel = sub->session->header.channel;
413	    if(!channel || !pre) {
414	        UA_LOG_DEBUG_SESSION(server->config.logger, sub->session,
415	                             "Subscription %u | Want to send a publish response but can't. "
416	                             "The subscription is late.", sub->subscriptionId);
417	        sub->state = UA_SUBSCRIPTIONSTATE_LATE;
418	        if(pre)
419	            UA_Session_queuePublishReq(sub->session, pre, true); /* Re-enqueue */
420	        return;
421	    }
422	
423	    /* Prepare the response */
424	    UA_PublishResponse *response = &pre->response;
425	    UA_NotificationMessage *message = &response->notificationMessage;
426	    UA_NotificationMessageEntry *retransmission = NULL;
427	    if(notifications > 0) {
428	        /* Allocate the retransmission entry */
429	        retransmission = (UA_NotificationMessageEntry*)UA_malloc(sizeof(UA_NotificationMessageEntry));
430	        if(!retransmission) {
431	            UA_LOG_WARNING_SESSION(server->config.logger, sub->session,
432	                                   "Subscription %u | Could not allocate memory for retransmission. "
433	                                   "The subscription is late.", sub->subscriptionId);
434	            sub->state = UA_SUBSCRIPTIONSTATE_LATE;
435	            UA_Session_queuePublishReq(sub->session, pre, true); /* Re-enqueue */
436	            return;
437	        }
438	
439	        /* Prepare the response */
440	        UA_StatusCode retval = prepareNotificationMessage(server, sub, message, notifications);
441	        if(retval != UA_STATUSCODE_GOOD) {
442	            UA_LOG_WARNING_SESSION(server->config.logger, sub->session,
443	                                   "Subscription %u | Could not prepare the notification message. "
444	                                   "The subscription is late.", sub->subscriptionId);
445	            UA_free(retransmission);
446	            sub->state = UA_SUBSCRIPTIONSTATE_LATE;
447	            UA_Session_queuePublishReq(sub->session, pre, true); /* Re-enqueue */
448	            return;
449	        }
450	    }
451	
452	    /* <-- The point of no return --> */
453	
454	    /* Adjust the number of ready notifications */
455	    UA_assert(sub->readyNotifications >= notifications);
456	    sub->readyNotifications -= notifications;
457	
458	    /* Set up the response */
459	    response->responseHeader.timestamp = UA_DateTime_now();
460	    response->subscriptionId = sub->subscriptionId;
461	    response->moreNotifications = moreNotifications;
462	    message->publishTime = response->responseHeader.timestamp;
463	
464	    /* Set sequence number to message. Started at 1 which is given
465	     * during creating a new subscription. The 1 is required for
466	     * initial publish response with or without an monitored item. */
467	    message->sequenceNumber = sub->nextSequenceNumber;
468	
469	    if(notifications > 0) {
470	        /* Put the notification message into the retransmission queue. This
471	         * needs to be done here, so that the message itself is included in the
472	         * available sequence numbers for acknowledgement. */
473	        retransmission->message = response->notificationMessage;
474	        UA_Subscription_addRetransmissionMessage(server, sub, retransmission);
475	        /* Only if a notification was created, the sequence number must be increased.
476	         * For a keepalive the sequence number can be reused. */
477	        sub->nextSequenceNumber = UA_Subscription_nextSequenceNumber(sub->nextSequenceNumber);
478	    }
479	
480	    /* Get the available sequence numbers from the retransmission queue */
481	    size_t available = sub->retransmissionQueueSize;
482	    UA_STACKARRAY(UA_UInt32, seqNumbers, available);
483	    if(available > 0) {
484	        response->availableSequenceNumbers = seqNumbers;
485	        response->availableSequenceNumbersSize = available;
486	        size_t i = 0;
487	        UA_NotificationMessageEntry *nme;
488	        TAILQ_FOREACH(nme, &sub->retransmissionQueue, listEntry) {
489	            response->availableSequenceNumbers[i] = nme->message.sequenceNumber;
490	            ++i;
491	        }
492	    }
493	
494	    /* Send the response */
495	    UA_LOG_DEBUG_SESSION(server->config.logger, sub->session,
496	                         "Subscription %u | Sending out a publish response "
497	                         "with %u notifications", sub->subscriptionId,
498	                         (UA_UInt32)notifications);
499	    UA_SecureChannel_sendSymmetricMessage(sub->session->header.channel, pre->requestId,
500	                                          UA_MESSAGETYPE_MSG, response,
501	                                          &UA_TYPES[UA_TYPES_PUBLISHRESPONSE]);
502	
503	    /* Reset subscription state to normal */
504	    sub->state = UA_SUBSCRIPTIONSTATE_NORMAL;
505	    sub->currentKeepAliveCount = 0;
506	
507	    /* Free the response */
508	    UA_Array_delete(response->results, response->resultsSize, &UA_TYPES[UA_TYPES_UINT32]);
509	    UA_free(pre); /* No need for UA_PublishResponse_deleteMembers */
510	
511	    /* Repeat sending responses if there are more notifications to send */
512	    if(moreNotifications)
513	        UA_Subscription_publish(server, sub);
514	}
515	
516	UA_Boolean
517	UA_Subscription_reachedPublishReqLimit(UA_Server *server,  UA_Session *session) {
518	    UA_LOG_DEBUG_SESSION(server->config.logger, session, "Reached number of publish request limit");
519	
520	    /* Dequeue a response */
521	    UA_PublishResponseEntry *pre = UA_Session_dequeuePublishReq(session);
522	
523	    /* Cannot publish without a response */
524	    if(!pre) {
525	        UA_LOG_FATAL_SESSION(server->config.logger, session, "No publish requests available");
526	        return false;
527	    }
528	
529	    /* <-- The point of no return --> */
530	
531	    UA_PublishResponse *response = &pre->response;
532	    UA_NotificationMessage *message = &response->notificationMessage;
533	
534	    /* Set up the response. Note that this response has no related subscription id */
535	    response->responseHeader.timestamp = UA_DateTime_now();
536	    response->responseHeader.serviceResult = UA_STATUSCODE_BADTOOMANYPUBLISHREQUESTS;
537	    response->subscriptionId = 0;
538	    response->moreNotifications = false;
539	    message->publishTime = response->responseHeader.timestamp;
540	    message->sequenceNumber = 0;
541	    response->availableSequenceNumbersSize = 0;
542	
543	    /* Send the response */
544	    UA_LOG_DEBUG_SESSION(server->config.logger, session,
545	                         "Sending out a publish response triggered by too many publish requests");
546	    UA_SecureChannel_sendSymmetricMessage(session->header.channel, pre->requestId,
547	                     UA_MESSAGETYPE_MSG, response, &UA_TYPES[UA_TYPES_PUBLISHRESPONSE]);
548	
549	    /* Free the response */
550	    UA_Array_delete(response->results, response->resultsSize, &UA_TYPES[UA_TYPES_UINT32]);
551	    UA_free(pre); /* no need for UA_PublishResponse_deleteMembers */
552	
553	    return true;
554	}
555	
556	UA_StatusCode
557	Subscription_registerPublishCallback(UA_Server *server, UA_Subscription *sub) {
558	    UA_LOG_DEBUG_SESSION(server->config.logger, sub->session,
559	                         "Subscription %u | Register subscription "
560	                         "publishing callback", sub->subscriptionId);
561	
562	    if(sub->publishCallbackIsRegistered)
563	        return UA_STATUSCODE_GOOD;
564	
565	    UA_StatusCode retval =
566	        UA_Server_addRepeatedCallback(server, (UA_ServerCallback)publishCallback,
567	                                      sub, (UA_UInt32)sub->publishingInterval, &sub->publishCallbackId);
568	    if(retval != UA_STATUSCODE_GOOD)
569	        return retval;
570	
571	    sub->publishCallbackIsRegistered = true;
572	    return UA_STATUSCODE_GOOD;
573	}
574	
575	UA_StatusCode
576	Subscription_unregisterPublishCallback(UA_Server *server, UA_Subscription *sub) {
577	    UA_LOG_DEBUG_SESSION(server->config.logger, sub->session, "Subscription %u | "
578	                         "Unregister subscription publishing callback", sub->subscriptionId);
579	
580	    if(!sub->publishCallbackIsRegistered)
581	        return UA_STATUSCODE_GOOD;
582	
583	    UA_StatusCode retval = UA_Server_removeRepeatedCallback(server, sub->publishCallbackId);
584	    if(retval != UA_STATUSCODE_GOOD)
585	        return retval;
586	
587	    sub->publishCallbackIsRegistered = false;
588	    return UA_STATUSCODE_GOOD;
589	}
590	
591	/* When the session has publish requests stored but the last subscription is
592	 * deleted... Send out empty responses */
593	void
594	UA_Subscription_answerPublishRequestsNoSubscription(UA_Server *server, UA_Session *session) {
595	    /* No session or there are remaining subscriptions */
596	    if(!session || LIST_FIRST(&session->serverSubscriptions))
597	        return;
598	
599	    /* Send a response for every queued request */
600	    UA_PublishResponseEntry *pre;
601	    while((pre = UA_Session_dequeuePublishReq(session))) {
602	        UA_PublishResponse *response = &pre->response;
603	        response->responseHeader.serviceResult = UA_STATUSCODE_BADNOSUBSCRIPTION;
604	        response->responseHeader.timestamp = UA_DateTime_now();
605	        UA_SecureChannel_sendSymmetricMessage(session->header.channel, pre->requestId, UA_MESSAGETYPE_MSG,
606	                                              response, &UA_TYPES[UA_TYPES_PUBLISHRESPONSE]);
607	        UA_PublishResponse_deleteMembers(response);
608	        UA_free(pre);
609	    }
610	}
611	
612	#endif /* UA_ENABLE_SUBSCRIPTIONS */
