249	static UA_StatusCode
250	browseAndBrowseNextRequest(UA_Client *client) {
251	    // Browse node in server folder
252	    UA_BrowseRequest bReq;
253	    UA_BrowseRequest_init(&bReq);
254	    // normally is set to 0, to get all the nodes, but we want to test browse next
255	    bReq.requestedMaxReferencesPerNode = 1;
256	    bReq.nodesToBrowse = UA_BrowseDescription_new();
257	    bReq.nodesToBrowseSize = 1;
258	    bReq.nodesToBrowse[0].nodeId = UA_NODEID_NUMERIC(0, UA_NS0ID_SERVER);
259	    bReq.nodesToBrowse[0].resultMask = UA_BROWSERESULTMASK_ALL;
260	
261	    UA_BrowseResponse bResp = UA_Client_Service_browse(client, bReq);
262	    ASSERT_GOOD(bResp.responseHeader.serviceResult);
263	
264	    // browse next
265	    UA_BrowseNextRequest bNextReq;
266	    UA_BrowseNextRequest_init(&bNextReq);
267	    // normally is set to 0, to get all the nodes, but we want to test browse next
268	    bNextReq.releaseContinuationPoints = UA_FALSE;
269	    bNextReq.continuationPoints = &bResp.results[0].continuationPoint;
270	    bNextReq.continuationPointsSize = 1;
271	
272	    UA_BrowseNextResponse bNextResp = UA_Client_Service_browseNext(client, bNextReq);
273	    ASSERT_GOOD(bNextResp.responseHeader.serviceResult);
274	
275	    UA_BrowseNextResponse_deleteMembers(&bNextResp);
276	
277	    bNextResp = UA_Client_Service_browseNext(client, bNextReq);
278	    ASSERT_GOOD(bNextResp.responseHeader.serviceResult);
279	
280	    UA_BrowseNextResponse_deleteMembers(&bNextResp);
281	
282	    // release continuation point. Result is then empty
283	    bNextReq.releaseContinuationPoints = UA_TRUE;
284	    bNextResp = UA_Client_Service_browseNext(client, bNextReq);
285	    UA_BrowseNextResponse_deleteMembers(&bNextResp);
286	    ASSERT_GOOD(bNextResp.responseHeader.serviceResult);
287	
288	    UA_BrowseRequest_deleteMembers(&bReq);
289	    UA_BrowseResponse_deleteMembers(&bResp);
290	    // already deleted by browse request
291	    bNextReq.continuationPoints = NULL;
292	    bNextReq.continuationPointsSize = 0;
293	    UA_BrowseNextRequest_deleteMembers(&bNextReq);
294	
295	    return UA_STATUSCODE_GOOD;
296	}
