327	static UA_StatusCode
328	translateBrowsePathsToNodeIdsRequest(UA_Client *client) {
329	    // Just for testing we want to translate the following path to its corresponding node id
330	    // /Objects/Server/ServerStatus/State
331	    // Equals the following node IDs:
332	    // /85/2253/2256/2259
333	
334	    #define BROWSE_PATHS_SIZE 3
335	    char *paths[BROWSE_PATHS_SIZE] = {"Server", "ServerStatus", "State"};
336	    UA_UInt32 ids[BROWSE_PATHS_SIZE] = {UA_NS0ID_ORGANIZES, UA_NS0ID_HASCOMPONENT, UA_NS0ID_HASCOMPONENT};
337	    UA_BrowsePath browsePath;
338	    UA_BrowsePath_init(&browsePath);
339	    browsePath.startingNode = UA_NODEID_NUMERIC(0, UA_NS0ID_OBJECTSFOLDER);
340	    browsePath.relativePath.elements = (UA_RelativePathElement*)UA_Array_new(BROWSE_PATHS_SIZE, &UA_TYPES[UA_TYPES_RELATIVEPATHELEMENT]);
341	    browsePath.relativePath.elementsSize = BROWSE_PATHS_SIZE;
342	
343	    for(size_t i = 0; i < BROWSE_PATHS_SIZE; i++) {
344	        UA_RelativePathElement *elem = &browsePath.relativePath.elements[i];
345	        elem->referenceTypeId = UA_NODEID_NUMERIC(0, ids[i]);
346	        elem->targetName = UA_QUALIFIEDNAME_ALLOC(0, paths[i]);
347	    }
348	
349	    UA_TranslateBrowsePathsToNodeIdsRequest request;
350	    UA_TranslateBrowsePathsToNodeIdsRequest_init(&request);
351	    request.browsePaths = &browsePath;
352	    request.browsePathsSize = 1;
353	
354	    UA_TranslateBrowsePathsToNodeIdsResponse response = UA_Client_Service_translateBrowsePathsToNodeIds(client, request);
355	    ASSERT_GOOD(response.responseHeader.serviceResult);
356	
357	    UA_BrowsePath_deleteMembers(&browsePath);
358	    UA_TranslateBrowsePathsToNodeIdsResponse_deleteMembers(&response);
359	
360	    return UA_STATUSCODE_GOOD;
361	}
