502	    UA_Variant_setScalarCopy(&input, &subId, &UA_TYPES[UA_TYPES_UINT32]);
503	    item.inputArgumentsSize = 1;
504	    item.inputArguments = &input;
505	
506	    request.methodsToCall = &item;
