565	int main(void) {
566	    emptyCorpusDir();
567	    start_server();
568	
569	    UA_Client *client = UA_Client_new(UA_ClientConfig_default);
570	    // this will also call getEndpointsRequest
571	    UA_StatusCode retval = UA_Client_connect(client, "opc.tcp://localhost:4840");
572	    if(retval == UA_STATUSCODE_GOOD)
573	        retval = executeClientServices(client);
574	    UA_Client_disconnect(client);
575	    UA_Client_delete(client);
576	
577	    if(retval == UA_STATUSCODE_GOOD) {
578	        // now also connect with user/pass so that fuzzer also knows how to do that
579	        client = UA_Client_new(UA_ClientConfig_default);
580	        retval = UA_Client_connect_username(client, "opc.tcp://localhost:4840", "user", "password");
581	        retval = retval == UA_STATUSCODE_BADUSERACCESSDENIED ? UA_STATUSCODE_GOOD : retval;
582	        UA_Client_disconnect(client);
583	        UA_Client_delete(client);
584	    }
585	
586	    teardown_server();
587	
588	    if(retval != UA_STATUSCODE_GOOD) {
589	        printf("\n--------- AN ERROR OCCURRED ----------\nStatus = %s\n", UA_StatusCode_name(retval));
590	        exit(1);
591	    } else {
592	        printf("\n--------- SUCCESS -------\nThe corpus is stored in %s", UA_CORPUS_OUTPUT_DIR);
593	    }
594	    return 0;
595	}
